"use client";

import {
  createContext,
  type HTMLAttributes,
  type ReactNode,
  type Ref,
  type RefObject,
  use,
  useEffect,
  useId,
  useMemo,
} from "react";
import { cn } from "../utils/cn";
import { Button, type ButtonProps } from "./button";
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from "./dialog";

/* -------------------------------------------------------------------------- *\
 *  Modal — Geist-flat API on top of Dialog (Base UI).
 *
 *  Use cases (per Geist guidance):
 *    Use a Modal when a decision must block the rest of the page. For
 *    persistent associated context where the underlying page stays readable,
 *    use Sheet on desktop or Drawer on mobile. Skip Modal for routine create
 *    flows that have a dedicated page; route to the page instead.
 *
 *  Compound surface:
 *    <Modal.Modal>          — root (controlled via `active`/`onClickOutside`)
 *      <Modal.Body>         — scrollable body
 *        <Modal.Header>     — header block
 *          <Modal.Title>    — Title Case statement, never a question
 *          <Modal.Subtitle> — sentence case, 1–3 sentences
 *        </Modal.Header>
 *        <Modal.Inset>      — bg-muted recessed panel
 *      </Modal.Body>
 *      <Modal.Actions>      — footer action row
 *        <Modal.Action>     — Button wrapper (type=primary|secondary)
 *      </Modal.Actions>
 *    </Modal.Modal>
 *
 *  Accessibility — encoded once, not at every call site:
 *    - `aria-labelledby` is auto-wired to <Modal.Title> via context so screen
 *      readers announce the title on open. No manual wiring required.
 *    - Focus trap, Escape-to-close, return-focus-to-trigger are inherited
 *      from Base UI's Dialog.
 *
 *  Destructive flows (caller responsibility):
 *    Default focus to Cancel on destructive modals. The pattern doesn't
 *    enforce this — pass `initialFocusRef` to the Cancel action. For
 *    high-stakes destructive (delete prod, rotate signing key, downgrade
 *    plan), gate the primary on a typed-match input — see DestructiveActionModal.
 *
 *  Sticky mode:
 *    When `sticky={true}`, the body region scrolls within a max-height while
 *    the actions row stays pinned at the bottom — useful for long forms or
 *    legal copy. The default lets the popup size to its content.
\* -------------------------------------------------------------------------- */

// ---------------------------------------------------------------------------
// Context — share titleId so Modal.Title auto-links via aria-labelledby
// ---------------------------------------------------------------------------

type ModalContextValue = {
  titleId: string;
  sticky: boolean;
};

const ModalContext = createContext<ModalContextValue | null>(null);

function useModalContext(): ModalContextValue {
  const ctx = use(ModalContext);
  if (!ctx) throw new Error("Modal.* must be used inside <Modal.Modal>");
  return ctx;
}

// ---------------------------------------------------------------------------
// Modal.Modal (root)
// ---------------------------------------------------------------------------

export interface ModalRootProps {
  /** Open state — controlled. */
  active: boolean;
  /** Called when the user clicks the backdrop (or presses Escape). */
  onClickOutside?: () => void;
  /**
   * Sticky mode: body scrolls within a max-height; actions stay pinned at
   * the bottom. @default false
   */
  sticky?: boolean;
  /**
   * Focus this element after the modal opens. Default focus is the first
   * focusable element. For destructive modals, point this at Cancel.
   */
  initialFocusRef?: RefObject<HTMLElement | null>;
  children: ReactNode;
  className?: string;
}

function ModalRoot({
  active,
  onClickOutside,
  sticky = false,
  initialFocusRef,
  children,
  className,
}: ModalRootProps) {
  const titleId = useId();
  const value = useMemo<ModalContextValue>(() => ({ titleId, sticky }), [titleId, sticky]);

  // Drive initialFocusRef once the modal opens. Base UI's Dialog has its own
  // focus-trap; we override the landing target after a tick so the trap finds
  // a target that's actually mounted.
  useEffect(() => {
    if (!active) return;
    const el = initialFocusRef?.current;
    if (!el) return;
    const id = requestAnimationFrame(() => {
      el.focus();
    });
    return () => cancelAnimationFrame(id);
  }, [active, initialFocusRef]);

  return (
    <ModalContext.Provider value={value}>
      <Dialog
        open={active}
        onOpenChange={(open) => {
          if (!open) onClickOutside?.();
        }}
      >
        <DialogContent
          aria-labelledby={titleId}
          className={cn(
            "max-w-md gap-0 p-0",
            sticky && "max-h-[85vh] grid grid-rows-[1fr_auto]",
            className,
          )}
        >
          {children}
        </DialogContent>
      </Dialog>
    </ModalContext.Provider>
  );
}

// ---------------------------------------------------------------------------
// Modal.Body
// ---------------------------------------------------------------------------

export type ModalBodyProps = HTMLAttributes<HTMLDivElement>;

const ModalBody = function ModalBody({
  className,
  ref,
  ...rest
}: ModalBodyProps & { ref?: Ref<HTMLDivElement> | undefined }) {
  const { sticky } = useModalContext();
  return (
    <div
      ref={ref}
      className={cn(
        "flex flex-col gap-4 px-6 pt-6 pb-4",
        sticky && "min-h-0 overflow-y-auto",
        className,
      )}
      {...rest}
    />
  );
};

// ---------------------------------------------------------------------------
// Modal.Header / Modal.Title / Modal.Subtitle
// ---------------------------------------------------------------------------

export type ModalHeaderProps = HTMLAttributes<HTMLDivElement>;

const ModalHeader = function ModalHeader({
  className,
  children,
  ref,
  ...rest
}: ModalHeaderProps & { ref?: Ref<HTMLDivElement> | undefined }) {
  return (
    <DialogHeader ref={ref} className={cn("space-y-2 text-left", className)} {...rest}>
      {children}
    </DialogHeader>
  );
};

export type ModalTitleProps = HTMLAttributes<HTMLHeadingElement>;

const ModalTitle = function ModalTitle({
  className,
  ref,
  ...rest
}: ModalTitleProps & { ref?: Ref<HTMLHeadingElement> | undefined }) {
  const { titleId } = useModalContext();
  // DialogTitle (Base UI) already renders <h2> with the right sizing. The
  // context-provided id wires aria-labelledby on the popup automatically.
  return (
    <DialogTitle
      ref={ref}
      id={titleId}
      className={cn("font-semibold text-foreground text-lg leading-tight", className)}
      {...rest}
    />
  );
};

export type ModalSubtitleProps = HTMLAttributes<HTMLParagraphElement>;

const ModalSubtitle = function ModalSubtitle({
  className,
  ref,
  ...rest
}: ModalSubtitleProps & { ref?: Ref<HTMLParagraphElement> | undefined }) {
  return (
    <p
      ref={ref}
      className={cn("text-muted-foreground text-sm leading-relaxed", className)}
      {...rest}
    />
  );
};

// ---------------------------------------------------------------------------
// Modal.Inset
// ---------------------------------------------------------------------------

export type ModalInsetProps = HTMLAttributes<HTMLDivElement>;

const ModalInset = function ModalInset({
  className,
  ref,
  ...rest
}: ModalInsetProps & { ref?: Ref<HTMLDivElement> | undefined }) {
  return (
    <div
      ref={ref}
      className={cn("-mx-6 my-2 border-border border-y bg-muted/40 px-6 py-4", className)}
      {...rest}
    />
  );
};

// ---------------------------------------------------------------------------
// Modal.Actions / Modal.Action
// ---------------------------------------------------------------------------

export type ModalActionsProps = HTMLAttributes<HTMLDivElement>;

const ModalActions = function ModalActions({
  className,
  children,
  ref,
  ...rest
}: ModalActionsProps & { ref?: Ref<HTMLDivElement> | undefined }) {
  const { sticky } = useModalContext();
  return (
    <DialogFooter
      ref={ref}
      className={cn(
        "flex-row items-center justify-end gap-2 border-border border-t px-6 py-4",
        sticky && "bg-background/95 backdrop-blur-sm",
        className,
      )}
      {...rest}
    >
      {children}
    </DialogFooter>
  );
};

export interface ModalActionProps extends Omit<ButtonProps, "variant" | "size" | "type"> {
  /** Geist Modal.Action "type" — primary or secondary. @default "primary" */
  type?: "primary" | "secondary";
  /** Stretch to fill the actions row (used in single-button modals). */
  fullWidth?: boolean;
  /** Optional leading glyph. */
  prefix?: ReactNode;
  /** HTML button type override (for forms). */
  buttonType?: "button" | "submit" | "reset";
  ref?: Ref<HTMLButtonElement>;
}

const ModalAction = function ModalAction({
  type = "primary",
  fullWidth,
  prefix,
  buttonType = "button",
  className,
  children,
  ref,
  ...rest
}: ModalActionProps & { ref?: Ref<HTMLButtonElement> | undefined }) {
  return (
    <Button
      ref={ref}
      type={buttonType}
      variant={type === "secondary" ? "secondary" : "default"}
      size="default"
      className={cn(fullWidth && "w-full", className)}
      {...rest}
    >
      {prefix && (
        <span aria-hidden="true" className="inline-flex shrink-0 [&_svg]:size-4">
          {prefix}
        </span>
      )}
      {children}
    </Button>
  );
};

// ---------------------------------------------------------------------------
// Compound export — Modal.Modal / Modal.Body / Modal.Header / Modal.Title /
// Modal.Subtitle / Modal.Inset / Modal.Actions / Modal.Action
// ---------------------------------------------------------------------------

/**
 * @example Basic create-resource modal
 * ```tsx
 * <Modal.Modal active={open} onClickOutside={() => setOpen(false)}>
 *   <Modal.Body>
 *     <Modal.Header>
 *       <Modal.Title>Create Token</Modal.Title>
 *       <Modal.Subtitle>Enter a unique name for your token.</Modal.Subtitle>
 *     </Modal.Header>
 *   </Modal.Body>
 *   <Modal.Actions>
 *     <Modal.Action type="secondary" onClick={() => setOpen(false)}>Cancel</Modal.Action>
 *     <Modal.Action onClick={() => handleCreate()}>Create Token</Modal.Action>
 *   </Modal.Actions>
 * </Modal.Modal>
 * ```
 *
 * @example Destructive modal — default focus on Cancel
 * ```tsx
 * const cancelRef = useRef<HTMLButtonElement>(null);
 * <Modal.Modal active={open} onClickOutside={() => setOpen(false)} initialFocusRef={cancelRef}>
 *   <Modal.Body>
 *     <Modal.Header>
 *       <Modal.Title>Delete Project</Modal.Title>
 *       <Modal.Subtitle>This cannot be undone.</Modal.Subtitle>
 *     </Modal.Header>
 *   </Modal.Body>
 *   <Modal.Actions>
 *     <Modal.Action ref={cancelRef} type="secondary" onClick={() => setOpen(false)}>Cancel</Modal.Action>
 *     <Modal.Action onClick={() => handleDelete()}>Delete Project</Modal.Action>
 *   </Modal.Actions>
 * </Modal.Modal>
 * ```
 */
export const Modal = {
  Modal: ModalRoot,
  Body: ModalBody,
  Header: ModalHeader,
  Title: ModalTitle,
  Subtitle: ModalSubtitle,
  Inset: ModalInset,
  Actions: ModalActions,
  Action: ModalAction,
} as const;

"use client";

import type { VariantProps } from "class-variance-authority";
import type * as React from "react";
import { cn } from "../utils/cn";
import { Slot } from "../utils/slot";
import { buttonVariants } from "./button-variants";

// ─── Spinner ──────────────────────────────────────────────────────────────────
// Uses @keyframes spinner from globals.css

function Spinner({ className }: { className?: string }) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        "block rounded-full border-2 border-current border-t-transparent animate-[spinner_0.6s_linear_infinite]",
        className,
      )}
    />
  );
}

// ─── Icon size class mapping ──────────────────────────────────────────────────

function getIconSizeClass(size: string | null | undefined): string {
  switch (size) {
    case "tiny":
      return "[&>svg]:size-3"; // 12px
    case "sm":
      return "[&>svg]:size-3.5"; // 14px
    case "lg":
      return "[&>svg]:size-4.5"; // 18px
    default:
      return "[&>svg]:size-4"; // 16px
  }
}

function getSpinnerSizeClass(size: string | null | undefined): string {
  switch (size) {
    case "tiny":
      return "size-3"; // 12px
    case "sm":
      return "size-3.5"; // 14px
    case "lg":
      return "size-4.5"; // 18px
    default:
      return "size-4"; // 16px
  }
}

// ─── Shadow class mapping ─────────────────────────────────────────────────────

const SHADOW_CLASSES: Record<string, string> = {
  sm: "shadow-sm",
  md: "shadow-md",
  lg: "shadow-md",
};

function resolveShadowClass(shadow: boolean | "sm" | "md" | "lg" | undefined): string | undefined {
  if (!shadow) return undefined;
  const level = shadow === true ? "md" : shadow;
  return SHADOW_CLASSES[level];
}

// ─── ButtonContent (shared between Button & ButtonLink) ───────────────────────

interface ButtonContentProps {
  loading: boolean;
  prefix?: React.ReactNode | undefined;
  suffix?: React.ReactNode | undefined;
  size?: string | null | undefined;
  children?: React.ReactNode | undefined;
}

function ButtonContent({ loading, prefix, suffix, size, children }: ButtonContentProps) {
  const iconSizeClass = getIconSizeClass(size);

  return (
    <>
      {loading && <Spinner className={getSpinnerSizeClass(size)} />}
      {prefix != null && (
        <span aria-hidden="true" className={cn("shrink-0", iconSizeClass)}>
          {prefix}
        </span>
      )}
      {children}
      {suffix != null && (
        <span aria-hidden="true" className={cn("shrink-0", iconSizeClass)}>
          {suffix}
        </span>
      )}
    </>
  );
}

// ─── Button ───────────────────────────────────────────────────────────────────

export interface ButtonProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "prefix">,
    VariantProps<typeof buttonVariants> {
  /** Render as a child element (Radix Slot — polymorphic) */
  asChild?: boolean;
  /** Show loading spinner and disable interaction */
  loading?: boolean;
  /** Icon or element rendered before children */
  prefix?: React.ReactNode;
  /** Icon or element rendered after children */
  suffix?: React.ReactNode;
  /** Elevation shadow level. `true` resolves to `"md"` */
  shadow?: boolean | "sm" | "md" | "lg";
}

const Button = ({
  className,
  variant,
  size,
  shape,
  asChild = false,
  loading = false,
  disabled,
  prefix,
  suffix,
  shadow,
  children,
  ref,
  ...props
}: ButtonProps & { ref?: React.Ref<HTMLButtonElement> | undefined }) => {
  const Comp = asChild ? Slot : "button";
  const isDisabled = Boolean(disabled || loading);
  const shadowClass = resolveShadowClass(shadow);

  return (
    <Comp
      ref={ref}
      className={cn(buttonVariants({ variant, size, shape }), shadowClass, className)}
      disabled={isDisabled}
      aria-busy={loading || undefined}
      {...props}
    >
      {asChild ? (
        children
      ) : (
        <ButtonContent loading={loading} prefix={prefix} suffix={suffix} size={size}>
          {children}
        </ButtonContent>
      )}
    </Comp>
  );
};
Button.displayName = "Button";

// ─── ButtonLink ───────────────────────────────────────────────────────────────

export interface ButtonLinkProps
  extends Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>, "prefix">,
    VariantProps<typeof buttonVariants> {
  /** Icon or element rendered before children */
  prefix?: React.ReactNode;
  /** Icon or element rendered after children */
  suffix?: React.ReactNode;
  /** Elevation shadow level. `true` resolves to `"md"` */
  shadow?: boolean | "sm" | "md" | "lg";
  /** Show loading spinner */
  loading?: boolean;
}

const ButtonLink = ({
  className,
  variant,
  size,
  shape,
  prefix,
  suffix,
  shadow,
  loading = false,
  children,
  ref,
  ...props
}: ButtonLinkProps & { ref?: React.Ref<HTMLAnchorElement> | undefined }) => {
  const shadowClass = resolveShadowClass(shadow);

  const loadingProps = loading
    ? {
        "aria-busy": "true" as const,
        "aria-disabled": "true" as const,
        tabIndex: -1,
      }
    : {};

  return (
    <a
      ref={ref}
      className={cn(
        buttonVariants({ variant, size, shape }),
        shadowClass,
        loading && "pointer-events-none opacity-50",
        className,
      )}
      {...loadingProps}
      {...props}
    >
      <ButtonContent loading={loading} prefix={prefix} suffix={suffix} size={size}>
        {children}
      </ButtonContent>
    </a>
  );
};
ButtonLink.displayName = "ButtonLink";

export { Button, ButtonLink };

"use client";

import { Dialog as BaseDialog } from "@base-ui/react/dialog";
import { Cross as X } from "@nebutra/icons";
import * as React from "react";
import { overlayClassNames, overlayZIndex } from "../tokens/components/overlay";
import { cn } from "../utils/cn";
import { overlayPrimitiveClassNames } from "./overlay";

// We keep these standard export names so the rest of the application using Nebutra UI doesn't break.
const Dialog = BaseDialog.Root;
const DialogPortal = BaseDialog.Portal;

const DialogTrigger = ({
  asChild,
  children,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseDialog.Trigger> & { asChild?: boolean } & {
  ref?: React.Ref<HTMLButtonElement> | undefined;
}) => {
  if (asChild && React.isValidElement(children)) {
    return (
      <BaseDialog.Trigger
        ref={ref}
        {...props}
        render={children as React.ReactElement<Record<string, unknown>>}
      />
    );
  }
  return (
    <BaseDialog.Trigger ref={ref} {...props}>
      {children}
    </BaseDialog.Trigger>
  );
};
DialogTrigger.displayName = "DialogTrigger";

const DialogClose = ({
  asChild,
  children,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseDialog.Close> & { asChild?: boolean } & {
  ref?: React.Ref<HTMLButtonElement> | undefined;
}) => {
  if (asChild && React.isValidElement(children)) {
    return (
      <BaseDialog.Close
        ref={ref}
        {...props}
        render={children as React.ReactElement<Record<string, unknown>>}
      />
    );
  }
  return (
    <BaseDialog.Close ref={ref} {...props}>
      {children}
    </BaseDialog.Close>
  );
};
DialogClose.displayName = "DialogClose";

const DialogOverlay = ({
  className,
  style,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseDialog.Backdrop> & {
  ref?: React.Ref<HTMLDivElement> | undefined;
}) => (
  <BaseDialog.Backdrop
    ref={ref}
    className={cn(overlayClassNames.backdrop, className)}
    style={{ zIndex: overlayZIndex.backdrop, ...style }}
    {...props}
  />
);
DialogOverlay.displayName = "DialogOverlay";

const DialogContent = ({
  className,
  children,
  style,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseDialog.Popup> & {
  ref?: React.Ref<HTMLDivElement> | undefined;
}) => (
  <DialogPortal>
    <DialogOverlay />
    <BaseDialog.Popup
      ref={ref}
      className={cn(
        overlayClassNames.modalSurface,
        overlayPrimitiveClassNames.modalSurface,
        className,
      )}
      style={{ zIndex: overlayZIndex.modal, ...style }}
      {...props}
    >
      {children}
      <DialogClose className={overlayClassNames.closeButton}>
        <X className="h-4 w-4" />
        <span className="sr-only">Close</span>
      </DialogClose>
    </BaseDialog.Popup>
  </DialogPortal>
);
DialogContent.displayName = "DialogContent";

const DialogHeader = ({
  className,
  ref,
  ...props
}: React.HTMLAttributes<HTMLDivElement> & { ref?: React.Ref<HTMLDivElement> | undefined }) => (
  <div
    ref={ref}
    className={cn("flex flex-col space-y-1.5 text-center sm:text-left", className)}
    {...props}
  />
);
DialogHeader.displayName = "DialogHeader";

const DialogFooter = ({
  className,
  ref,
  ...props
}: React.HTMLAttributes<HTMLDivElement> & { ref?: React.Ref<HTMLDivElement> | undefined }) => (
  <div
    ref={ref}
    className={cn("flex flex-col-reverse sm:flex-row sm:justify-end sm:space-x-2", className)}
    {...props}
  />
);
DialogFooter.displayName = "DialogFooter";

const DialogTitle = ({
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseDialog.Title> & {
  ref?: React.Ref<HTMLHeadingElement> | undefined;
}) => (
  <BaseDialog.Title
    ref={ref}
    className={cn("text-lg font-semibold leading-none tracking-tight", className)}
    {...props}
  />
);
DialogTitle.displayName = "DialogTitle";

const DialogDescription = ({
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseDialog.Description> & {
  ref?: React.Ref<HTMLParagraphElement> | undefined;
}) => (
  <BaseDialog.Description
    ref={ref}
    className={cn("text-sm text-muted-foreground", className)}
    {...props}
  />
);
DialogDescription.displayName = "DialogDescription";

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
  DialogTrigger,
};

import { cva } from "class-variance-authority";

// Heights / weights from recipe.css (--control-height-*, --font-weight-medium).
// Focus ring uses shared ring token.
export const buttonVariants = cva(
  [
    "inline-flex items-center justify-center gap-2 whitespace-nowrap",
    "rounded-[var(--btn-default-radius,var(--radius-md))]",
    "text-[length:var(--control-font-size-md,0.875rem)] font-[number:var(--font-weight-medium,500)]",
    "transition-colors duration-micro ease-out",
    "disabled:pointer-events-none disabled:opacity-50",
    "aria-busy:cursor-wait",
  ].join(" "),
  {
    variants: {
      variant: {
        // Recipe-driven via packages/design/tokens/recipe.css (.btn-brand-default)
        default: "btn-brand-default",
        ink: "bg-[var(--neutral-12)] text-[var(--neutral-1)] ring-1 ring-inset ring-[color:var(--neutral-1)]/5 hover:bg-[var(--neutral-11)] hover:-translate-y-px active:translate-y-0 transition-[transform,background-color] duration-micro",
        destructive: "bg-destructive text-destructive-foreground hover:bg-destructive/90",
        outline: "border border-input bg-background hover:bg-accent hover:text-accent-foreground",
        secondary: "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        link: "text-primary underline-offset-4 hover:underline",
        tertiary:
          "border border-transparent bg-transparent text-muted-foreground hover:bg-accent hover:text-accent-foreground hover:border-input",
        warning: "bg-warning text-warning-foreground hover:bg-warning/90",
      },
      size: {
        tiny: "h-[var(--control-height-tiny,1.5rem)] rounded-[var(--radius-sm)] px-2 text-[length:var(--control-font-size-tiny,0.6875rem)]",
        sm: "h-[var(--control-height-sm,2rem)] rounded-[var(--radius-sm)] px-3 text-[length:var(--control-font-size-sm,0.75rem)]",
        default:
          "h-[var(--control-height-md,2.5rem)] px-[var(--btn-default-padding-x,1rem)] py-[var(--btn-default-padding-y,0.5rem)]",
        lg: "h-[var(--control-height-lg,3rem)] rounded-[var(--radius-lg)] px-5 text-[length:var(--control-font-size-lg,1rem)]",
        icon: "h-[var(--control-height-md,2.5rem)] w-[var(--control-height-md,2.5rem)]",
      },
      shape: {
        default: "",
        square: "",
        circle: "",
      },
    },
    compoundVariants: [
      { shape: "square", size: "tiny", className: "w-[var(--control-height-tiny,1.5rem)] px-0" },
      { shape: "square", size: "sm", className: "w-[var(--control-height-sm,2rem)] px-0" },
      { shape: "square", size: "default", className: "w-[var(--control-height-md,2.5rem)] px-0" },
      { shape: "square", size: "lg", className: "w-[var(--control-height-lg,3rem)] px-0" },
      {
        shape: "circle",
        size: "tiny",
        className: "w-[var(--control-height-tiny,1.5rem)] px-0 rounded-full",
      },
      {
        shape: "circle",
        size: "sm",
        className: "w-[var(--control-height-sm,2rem)] px-0 rounded-full",
      },
      {
        shape: "circle",
        size: "default",
        className: "w-[var(--control-height-md,2.5rem)] px-0 rounded-full",
      },
      {
        shape: "circle",
        size: "lg",
        className: "w-[var(--control-height-lg,3rem)] px-0 rounded-full",
      },
    ],
    defaultVariants: {
      variant: "default",
      size: "default",
      shape: "default",
    },
  },
);
